WITH orders_by_customer AS (SELECT customer_id, MAX(amount) max_amount, ROUND((100 * SUM(CASE WHEN status = 'SHIPPED' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_shipped FROM orders WHERE order_date <= '2024-01-09' GROUP BY customer_id) SELECT customers.id, customers.segment, customers.name, orders_by_customer.max_amount, orders_by_customer.pct_shipped FROM customers LEFT OUTER JOIN orders_by_customer ON customers.id = orders_by_customer.customer_id WHERE orders_by_customer.pct_shipped > 31 ORDER BY id DESC, orders_by_customer.pct_shipped DESC;
